import java.util.Calendar;
import java.util.Date;
import java.util.GregorianCalendar;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.TimeZone;
import org.apache.commons.lang.Validate;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertSame;

public class FastDateFormat_getDateTimeInstance_TriageGen2Test {

    @Test
    public void testGetDateTimeInstance_WithAllParameters() {
        int dateStyle = Calendar.MEDIUM;
        int timeStyle = Calendar.SHORT;
        TimeZone timeZone = TimeZone.getTimeZone("GMT");
        Locale locale = Locale.US;

        FastDateFormat format1 = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle, timeZone, locale);
        assertNotNull(format1);
        assertEquals(timeZone, format1.getTimeZone());
        assertEquals(locale, format1.getLocale());

        // Test Cache: calling with same parameters should return the same instance
        FastDateFormat format2 = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle, timeZone, locale);
        assertSame("Should return cached instance", format1, format2);
    }

    @Test
    public void testGetDateTimeInstance_WithNullTimeZone() {
        int dateStyle = Calendar.LONG;
        int timeStyle = Calendar.LONG;
        TimeZone timeZone = null;
        Locale locale = Locale.FRANCE;

        FastDateFormat format = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle, timeZone, locale);
        assertNotNull(format);
        assertEquals(locale, format.getLocale());
        // When timeZone is null, the internal getInstance usually defaults to GMT or system default depending on implementation, 
        // but we verify the logic flow for the null check.
    }

    @Test
    public void testGetDateTimeInstance_WithNullLocale() {
        int dateStyle = Calendar.SHORT;
        int timeStyle = Calendar.SHORT;
        TimeZone timeZone = TimeZone.getDefault();
        Locale locale = null;

        // This tests the branch: if (locale == null) { locale = Locale.getDefault(); }
        FastDateFormat format = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle, timeZone, locale);
        assertNotNull(format);
        assertEquals(Locale.getDefault(), format.getLocale());
    }

    @Test
    public void testGetDateTimeInstance_WithNullAll() {
        int dateStyle = Calendar.DEFAULT;
        int timeStyle = Calendar.DEFAULT;

        // Testing the scenario where both TimeZone and Locale are null
        FastDateFormat format = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle, null, null);
        assertNotNull(format);
        assertEquals(Locale.getDefault(), format.getLocale());
    }

    @Test
    public void testGetDateTimeInstance_DifferentCombinationsCache() {
        int dateStyle = Calendar.MEDIUM;
        int timeStyle = Calendar.MEDIUM;
        TimeZone tz1 = TimeZone.getTimeZone("UTC");
        TimeZone tz2 = TimeZone.getTimeZone("EST");
        Locale loc1 = Locale.US;
        Locale loc2 = Locale.UK;

        FastDateFormat f1 = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle, tz1, loc1);
        FastDateFormat f2 = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle, tz2, loc1);
        FastDateFormat f3 = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle, tz1, loc2);
        FastDateFormat f4 = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle, tz1, loc1);

        assertNotNull(f1);
        assertNotNull(f2);
        assertNotNull(f3);
        assertSame("Cache hit for identical parameters", f1, f4);
    }
}
